import hou, numpy as np
bf = hou.node('/obj/butterfly')
skin = hou.node('/obj/girl/geo_skin').displayNode()
PARTS = {}
for n in ['body', 'wing_fore_L', 'wing_hind_L', 'wing_fore_R', 'wing_hind_R']:
    geo = bf.node(n).displayNode().geometry(); P = np.array(geo.pointFloatAttribValues('P')).reshape(-1, 3)
    PARTS[n] = P[::max(1, len(P) // NPTS)]
DIRS = [np.array(v, float) / np.linalg.norm(v) for v in [(0, 1, 0), (0.3, 0.2, 1), (-1, 0.2, 0.1), (0.5, -0.4, -0.8), (0, -1, 0.1)]]
def inside(geo, p):
    votes = 0
    for d in DIRS:
        P = hou.Vector3(); N = hou.Vector3(); uvw = hou.Vector3()
        pid = geo.intersect(hou.Vector3(p.tolist()), hou.Vector3(d.tolist()), P, N, uvw, min_hit=1e-6, max_hit=0.3)
        if pid >= 0 and np.dot(np.array(N), d) > 0: votes += 1
    return votes >= 3
PEN = {}; MIND = {}
for f in FRAMES:
    hou.setFrame(f); geo = skin.geometry()
    c = np.array(bf.node('CTRL_body').worldTransform().extractTranslates())
    r0 = geo.nearestPrim(hou.Vector3(c.tolist()))
    if r0[3] > 0.12:
        MIND[f] = (r0[3], 'center'); continue
    best = (9, '')
    for n, P in PARTS.items():
        m = np.array(bf.node(n).worldTransform().asTupleOfTuples())
        W = (np.c_[P, np.ones(len(P))] @ m)[:, :3]
        for q in W:
            d = geo.nearestPrim(hou.Vector3(q.tolist()))[3]
            if d < best[0]: best = (d, n)
            if d < 0.012 and inside(geo, q): PEN[(f, n)] = PEN.get((f, n), 0) + 1
    MIND[f] = best

